import numpy as np
def equation(eps, T, params):
    a,b,p,f,g,c,k,d,h,m=params[0],params[1],params[2],params[3],params[4],params[5],params[6],params[7],params[8],params[9]
    u=T-2
    return -(a*np.tanh(b*eps**p*np.exp(f*u))*np.exp(g*u) + c*np.abs(u)**k*eps**d*np.exp(h*u) + m*eps*np.exp(0.2*u))
